.darma-loader-tw-upload-arrow { position: relative; display: inline-block; width: var(--loader-size, 64px); height: var(--loader-size, 64px); }
.darma-loader-tw-upload-arrow .darma-loader-tw-upload-arrow__arrow { position: absolute; left: 50%; top: 14%; width: calc(var(--loader-size, 64px) * .09); height: 44%; margin-left: calc(var(--loader-size, 64px) * -.045); border-radius: 9999px; background: var(--loader-color, #3b82f6); animation: darma-loader-tw-upload-arrow-twUp calc(var(--loader-speed, 1s) * 1.4) ease-in-out infinite; }
.darma-loader-tw-upload-arrow .darma-loader-tw-upload-arrow__arrow::before { content: ''; position: absolute; top: calc(var(--loader-size, 64px) * -.02); left: 50%; width: calc(var(--loader-size, 64px) * .22); height: calc(var(--loader-size, 64px) * .22); margin-left: calc(var(--loader-size, 64px) * -.11); border-top: calc(var(--loader-size, 64px) * .09) solid var(--loader-color, #3b82f6); border-left: calc(var(--loader-size, 64px) * .09) solid var(--loader-color, #3b82f6); border-radius: calc(var(--loader-size, 64px) * .03); transform: rotate(45deg); }
.darma-loader-tw-upload-arrow .darma-loader-tw-upload-arrow__tray { position: absolute; left: 14%; bottom: 10%; width: 72%; height: 22%; border: calc(var(--loader-size, 64px) * .06) solid color-mix(in srgb, var(--loader-color, #3b82f6) 45%, transparent); border-top: 0; border-radius: 0 0 calc(var(--loader-size, 64px) * .1) calc(var(--loader-size, 64px) * .1); box-sizing: border-box; }
@keyframes darma-loader-tw-upload-arrow-twUp { 0%, 100% { transform: translateY(20%); opacity: .45; } 50% { transform: translateY(-8%); opacity: 1; } }

